export class SecurityError extends Error {constructor(message,status=403){super(message);this.status=status;}}
const owners=new WeakMap(),clients=new WeakMap();
export function trustOwner(request,id){owners.set(request,id);}
export function trustedOwner(request){return owners.get(request);}
export function trustClient(request,address){clients.set(request,address||'unknown');}
export function trustedClient(request){return clients.get(request)||'unknown';}
export const productionOrigin='https://tristone.ae';
export function approvedOrigin(origin,env={}){if(origin===productionOrigin)return true;if(env.DEPLOYMENT_STAGE!=='test'||!env.TEST_ORIGIN)return false;try{const u=new URL(env.TEST_ORIGIN);return u.protocol==='https:'&&u.origin===env.TEST_ORIGIN&&!u.username&&!u.password&&origin===u.origin;}catch{return false;}}
export function requireOrigin(request,env){const origin=request.headers.get('origin');if(!approvedOrigin(origin,env))throw new SecurityError('This website origin is not approved.');return origin;}
export async function digest(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',typeof value==='string'?new TextEncoder().encode(value):value))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function hmac(value,secret){if(typeof secret!=='string'||secret.length<32)throw new SecurityError('Server security is not configured.',503);const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export function equal(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let n=0;for(let i=0;i<a.length;i++)n|=a.charCodeAt(i)^b.charCodeAt(i);return n===0;}
export async function readBounded(request,limit){if(Number(request.headers.get('content-length')||0)>limit)throw new SecurityError('Request is too large.',413);const reader=request.body?.getReader();if(!reader)return new Uint8Array();const chunks=[];let size=0;for(;;){const r=await reader.read();if(r.done)break;size+=r.value.length;if(size>limit){await reader.cancel();throw new SecurityError('Request is too large.',413);}chunks.push(r.value);}return new Uint8Array(await new Blob(chunks).arrayBuffer());}
export async function consume(env,key,amount,limit,expires){if(!env.DB)throw new SecurityError('Security storage is unavailable.',503);if(!Number.isSafeInteger(amount)||amount<0||amount>limit)throw new SecurityError('Storage limit exceeded.',429);const r=await env.DB.prepare('INSERT INTO security_counters (id, used, expires) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET used = used + excluded.used WHERE used + excluded.used <= ? RETURNING used').bind(key,amount,expires,limit).first();if(!r||amount>limit)throw new SecurityError('The request limit has been reached. Please try later.',429);}
export async function rateLimit(request,env,group='submission'){if(!env.DB)throw new SecurityError('Security storage is unavailable.',503);await env.DB.prepare('DELETE FROM security_nonces WHERE id IN (SELECT id FROM security_nonces WHERE expires < ? LIMIT 100)').bind(Date.now()).run();await env.DB.prepare('DELETE FROM security_counters WHERE id IN (SELECT id FROM security_counters WHERE expires > 0 AND expires < ? LIMIT 100)').bind(Date.now()).run();await env.DB.prepare('DELETE FROM admin_sessions WHERE id IN (SELECT id FROM admin_sessions WHERE expires < ? LIMIT 100)').bind(Date.now()).run();const now=Date.now(),window=Math.floor(now/600000),client=await digest(trustedClient(request));await consume(env,'rate:'+group+':global:'+window,1,group==='login'?100:group==='gateway'?1000:200,now+1200000);await consume(env,'rate:'+group+':client:'+client+':'+window,1,group==='login'?5:group==='gateway'?200:10,now+1200000);}
export async function reserveStorage(env,bytes){const now=Date.now(),day=new Date(now+4*3600000).toISOString().slice(0,10);await consume(env,'submissions:'+day,1,200,now+172800000);await consume(env,'storage:day:'+day,bytes,50*1024*1024,now+172800000);await consume(env,'storage:lifetime',bytes,500*1024*1024,0);}
export async function verifyGateway(request,env){const encoded=request.headers.get('x-tristone-proof');if(!encoded)return false;if(!env.HOSTINGER_BRIDGE_SECRET)throw new SecurityError('Hostinger access is not configured.',503);let proof;try{proof=JSON.parse(encoded);}catch{throw new SecurityError('Invalid gateway authentication.');}const {timestamp,nonce,client,session,signature}=proof;if(!Number.isSafeInteger(timestamp)||Math.abs(Date.now()-timestamp)>60000||!/^[a-f0-9-]{36}$/.test(nonce)||typeof client!=='string'||client.length>100||typeof session!=='string'||session.length>100)throw new SecurityError('Invalid gateway authentication.');const body=await readBounded(request,11*1024*1024);const u=new URL(request.url);const canonical=JSON.stringify({timestamp,nonce,client,session,method:request.method,path:u.pathname+u.search,origin:request.headers.get('origin')||'',body:await digest(body)});if(!equal(signature,await hmac(canonical,env.HOSTINGER_BRIDGE_SECRET)))throw new SecurityError('Invalid gateway authentication.');if(!env.DB)throw new SecurityError('Security storage unavailable.',503);trustClient(request,client);await rateLimit(request,env,'gateway');const inserted=await env.DB.prepare('INSERT INTO security_nonces (id, expires) VALUES (?, ?) ON CONFLICT(id) DO NOTHING').bind(nonce,Date.now()+120000).run();if(inserted.meta?.changes!==1)throw new SecurityError('Gateway request has already been used.');trustClient(request,client);if(session){const row=await env.DB.prepare('SELECT id FROM admin_sessions WHERE id = ? AND expires > ?').bind(await digest(session),Date.now()).first();if(row)trustOwner(request,'hostinger-owner');}return {body,session};}
